'use strict';
const F=Finance,KEY='mon-budget-serein-v1';
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',income:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',expense:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',wallet:'M20 8V5H4a2 2 0 0 0 0 4h16v11H4a2 2 0 0 1-2-2V7 M20 12h-5v4h5',goal:'M21 12a9 9 0 1 1-3-6 M12 3v3 M3 12h3 M12 18v3 M18 12h3 M12 8a4 4 0 1 0 4 4 M12 12l8-8',chart:'M3 3v18h18 M7 16l4-6 4 3 6-9',sliders:'M4 4v4 m0 4v8 M12 4v9 m0 4v3 M20 4v2 m0 4v10 M1 8h6 M9 13h6 M17 6h6',report:'M6 3h9l4 4v14H5V3z M14 3v5h5 M8 12h8 M8 16h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h1 M15 14h1 M8 17h1',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',plus:'M12 5v14 M5 12h14',down:'M12 3v15 m-5-5 5 5 5-5 M4 20h16',up:'M12 21V6 m-5 5 5-5 5 5 M4 3h16',arrow:'M4 12h16 m-5-5 5 5-5 5',check:'m5 12 4 4L20 5',close:'m6 6 12 12 M6 18 18 6',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',basket:'M3 9h18l-2 11H5z M7 9l5-7 5 7 M9 12v5 M15 12v5',car:'m5 7 2-4h10l2 4 M3 8h18v10H3z M6 18v3 M18 18v3 M6 12h2 M16 12h2',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h.01',heart:'M12 21 3 12C-2 4 8-1 12 6c4-7 14-2 9 6z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z m-5 10 3 3 5-5',bolt:'m13 2-9 12h7l-1 8 10-13h-8z',edit:'m15 4 5 5 M4 20l5-1L21 7l-5-5L4 14z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7h.01',refresh:'M20 7V3l-3 3 M4 17v4l3-3 M20 7A9 9 0 0 0 4 7 M4 17a9 9 0 0 0 16 0',menu:'M4 6h16 M4 12h16 M4 18h16',transfer:'M3 7h17l-4-4 M21 17H4l4 4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v7H6z M17 11h1',percent:'M5 19 19 5 M6 4a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M18 16a2 2 0 1 0 0 4 2 2 0 0 0 0-4'};
const I=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.wallet}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let loadError='';let S;try{const raw=localStorage.getItem(KEY);S=raw?F.validateState(JSON.parse(raw)):F.fresh()}catch(e){S=F.fresh();loadError='La sauvegarde locale n’a pas pu être lue. Elle a été conservée ; exportez-la avant de remplacer les données.'}
let month=F.today().slice(0,7),page='dashboard',filters={q:'',category:'',status:'',nature:'',source:''},comparison='six',year=+month.slice(0,4),menuOpen=false,simulation={raise:0,extra:0,cut:10,saving:0,target:0,purchase:0};
const pages={dashboard:['Tableau de bord','grid'],income:['Mes revenus','income'],expense:['Mes dépenses','expense'],budget:['Mon budget','wallet'],saving:['Mon épargne','goal'],analysis:['Analyses','chart'],simulator:['Simulateur','sliders'],calendar:['Calendrier','calendar'],reports:['Rapports','report'],settings:['Paramètres','settings']};
F.ensureMonth(S,month);
function persist(){try{localStorage.setItem(S.demo?KEY+'-demo':KEY,JSON.stringify(S));return true}catch{toast('Sauvegarde impossible. Exportez vos données pour les conserver.');return false}}
function money(n,short=false){const v=n/100;return new Intl.NumberFormat('fr-FR',{maximumFractionDigits:v%1?2:0,minimumFractionDigits:0,...(short?{notation:'compact'}:{})}).format(v)+(S.settings.currency==='XOF'||S.settings.currency==='XAF'?' FCFA':' '+({EUR:'€',USD:'$ US',GBP:'£',CAD:'$ CA',MAD:'MAD',GNF:'GNF'}[S.settings.currency]||S.settings.currency))}
const numInput=n=>n?String(n/100):'0';const pct=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n)+' %';
const monthName=(m=month)=>new Date(m+'-02T00:00:00Z').toLocaleDateString('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'});
const dateName=d=>new Date(d+'T00:00:00Z').toLocaleDateString('fr-FR',{day:'2-digit',month:'short',timeZone:'UTC'});
const cat=id=>S.categories.find(c=>c.id===id);const kindNames={income:'Revenu',expense:'Dépense',saving:'Épargne',transfer:'Transfert interne'};
const typeNames={fixed:'Fixe',variable:'Variable',exceptional:'Exceptionnelle'};const freqNames={once:'Ponctuelle',weekly:'Hebdomadaire',monthly:'Mensuelle',quarterly:'Trimestrielle',yearly:'Annuelle'};
const incomeSources=['Salaire principal (net)','Salaire secondaire','Activités indépendantes / Freelance','Revenus commerciaux','Revenus passifs','Primes et commissions','Autres revenus'];
const progress=(value,limit)=>{const p=limit?value/limit*100:0;return `<div class="progress ${p>100?'red':p>=80?'orange':''}" role="progressbar" aria-label="Utilisation" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(p))}"><span style="width:${Math.max(0,Math.min(p,100))}%"></span></div>`};
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500)}
function navigate(p){page=p;filters={q:'',category:'',status:'',nature:'',source:''};menuOpen=false;render();window.scrollTo({top:0,behavior:'instant'})}
const button=(text,action,icon='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}">${icon?I(icon):''}${text}</button>`;
function render(){
 document.body.classList.toggle('dark',S.settings.theme==='dark');
 const title=pages[page][0];const first=page==='dashboard';const q=F.metrics(S,month);
 document.getElementById('app').innerHTML=`<aside class="sidebar ${menuOpen?'open':''}" aria-label="Navigation principale"><div class="brand"><span class="brand-mark">✳</span><span class="brand-name">Budget Perso<span style="color:#cddb9e">.</span></span></div><div class="brand-sub">L’esprit tranquille.</div><div class="nav-label">MON ESPACE FINANCIER</div><nav class="nav">${Object.entries(pages).filter(([k])=>k!=='settings').map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${I(v[1])}${v[0]}</button>`).join('')}</nav><div class="nav-divider"></div><nav class="nav"><button data-page="settings" class="${page==='settings'?'active':''}">${I('settings')}Paramètres</button></nav><div class="sidebar-bottom"><div class="local-note"><strong>${I('lock')}Votre espace personnel</strong>Vos chiffres sont enregistrés dans ce navigateur. Pensez à les sauvegarder.</div><div class="profile"><div class="avatar">${esc(S.settings.name?.slice(0,1).toUpperCase()||'M')}</div><div><strong>${esc(S.settings.name||'Mon espace personnel')}</strong><small>${S.demo?'Mode démonstration':'À votre rythme, chaque mois'}</small></div></div></div></aside><div class="backdrop ${menuOpen?'open':''}" data-action="menu"></div><div class="shell"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Ouvrir le menu">${I('menu')}</button>${I('home')}<span>Mon espace</span><span>/</span><b>${title}</b></div><div class="top-actions"><span class="secure">Sauvegarde locale</span><button class="icon-btn" data-action="theme" aria-label="Activer le mode ${S.settings.theme==='dark'?'clair':'sombre'}">${I(S.settings.theme==='dark'?'sun':'moon')}</button><div class="avatar" aria-label="Profil">${esc(S.settings.name?.slice(0,1).toUpperCase()||'M')}</div></div></header><main id="main" class="page-enter"><div class="page-head"><div><div class="eyebrow">${first?'Votre argent, vos projets':'Budget Perso'}</div><h1>${first?'Une vision claire de vos finances.':({income:'Mes Revenus Mensuels',expense:'Mes Dépenses Mensuelles',budget:'Planification de mon Budget',saving:'Mon Plan d’Épargne',analysis:'Analyse Intelligente de Mes Finances',simulator:'Simulateur Financier',calendar:'Mon Calendrier Financier',reports:'Mon Bilan Financier du Mois',settings:'Un espace à votre image'})[page]}</h1><p class="lead">${first?'Budget, Dépenses & Épargne — avancez sereinement, un mois à la fois.':({income:'Chaque source de revenu a sa place.',expense:'Comprenez où va votre argent, au quotidien.',budget:'Donnez une direction à chaque franc.',saving:'Les petits pas d’aujourd’hui financent vos projets de demain.',analysis:'Des constats concrets, calculés à partir de vos données.',simulator:'Explorez vos possibilités avant de décider.',calendar:'Vos mouvements et vos échéances, au même endroit.',reports:'Prenez du recul pour mieux préparer le mois suivant.',settings:'Vos préférences, vos catégories et vos sauvegardes.'})[page]}</p></div><div class="head-actions">${page!=='settings'?`<div class="month-control"><button data-action="prev" aria-label="Mois précédent">${I('left')}</button><input type="month" id="month" value="${month}" min="1900-01" max="2199-12" aria-label="Mois sélectionné"><button data-action="next" aria-label="Mois suivant">${I('chevron')}</button></div>`:''}${first||page==='income'||page==='expense'?button((page==='income'?'Ajouter un revenu':page==='expense'?'Ajouter une dépense':'Ajouter un mouvement'),'add-'+(page==='income'?'income':'expense'),'plus','primary'):page==='saving'?button('Nouvel objectif','goal','plus','primary'):''}</div></div>${S.demo?`<div class="demo-banner"><span>${I('info')} Données fictives · Cette démonstration ne représente pas vos finances.</span><button class="text-btn" data-action="exit-demo">Quitter</button></div>`:''}${loadError?`<div class="notice error">${esc(loadError)}</div>`:''}<div id="page-content">${({dashboard:dashboard,income:()=>transactionPage('income'),expense:()=>transactionPage('expense'),budget:budgetPage,saving:savingPage,analysis:analysisPage,simulator:simulatorPage,calendar:calendarPage,reports:reportsPage,settings:settingsPage})[page](q)}</div><footer class="footer"><span>Budget Perso — Budget, Dépenses & Épargne</span><span>${I('lock')} Données locales · ${S.settings.currency} · Sans connexion bancaire</span></footer></main></div>`;
 bind();
}
function stat(label,n,icon,note,featured=false,isPercent=false){return `<article class="stat ${featured?'featured':''}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${I(icon)}</span></div><div class="number">${isPercent?pct(n):esc(money(n)).replace(/ (FCFA|€|\$ US|£|\$ CA|MAD|GNF)$/,'<span class="unit">$1</span>')}</div><small>${I('info')}${note}</small></article>`}
function dashboard(q){return `${!S.transactions.length?`<div class="intro"><div><div class="intro-title">Votre nouveau départ financier ${I('spark')}</div><p>Commencez par votre premier revenu. Le reste prendra forme, simplement.</p></div><div class="intro-actions">${button('Ajouter un revenu','add-income','plus','primary')}${button('Explorer un exemple fictif','demo','arrow')}</div></div>`:''}<section class="stats" aria-label="Résumé du mois">${stat('Revenus totaux',q.income,'income',q.expected?money(q.expected)+' attendus':'Revenus reçus ce mois-ci')}${stat('Dépenses totales',q.spent,'expense',q.planned?money(q.planned)+' encore prévus':'Dépenses payées ce mois-ci')}${stat('Épargne du mois',q.saved,'goal','Versements réellement effectués')}${stat('Solde disponible',q.available,'wallet','Après épargne et dépenses prévues',true)}${stat('Taux d’épargne',q.rate,'percent','Épargne versée / revenus reçus',false,true)}${stat('Budget restant',q.remaining,'chart',q.totalBudget?'Dépenses prévues incluses':'Définissez votre budget')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Votre équilibre au fil des mois</h2><p class="panel-sub">Revenus, dépenses payées et épargne versée</p></div><span class="badge">6 derniers mois</span></div>${barsChart(q)}<div class="chart-legend"><span><i class="dot" style="background:#4d7359"></i>Revenus</span><span><i class="dot" style="background:#b8c9a0"></i>Dépenses</span><span><i class="dot" style="background:#e4bd7e"></i>Épargne</span></div></section><section class="panel"><div class="panel-head"><div><h2>Où va votre argent ?</h2><p class="panel-sub">Dépenses payées, par catégorie</p></div><span class="badge">${q.byCategory.filter(c=>c.paid).length} catégories</span></div>${donutChart(q)}</section><section class="panel"><div class="panel-head"><div><h2>Un budget qui vous ressemble</h2><p class="panel-sub">Dépenses payées et prévues</p></div><button class="text-btn" data-page="budget">Gérer ${I('arrow')}</button></div>${budgetOverview(q)}</section><section class="panel"><div class="panel-head"><div><h2>Vos projets prennent vie</h2><p class="panel-sub">Un pas de plus vers vos objectifs</p></div><button class="text-btn" data-page="saving">Voir tout ${I('arrow')}</button></div>${S.goals.length?S.goals.slice(0,2).map(g=>miniGoal(g)).join(''):`<div class="project-card"><div class="project-icon">${I('goal')}</div><div class="project-info"><p>Quel sera votre premier projet ?</p><small>Un fonds d’urgence, un voyage, une idée…</small></div></div>${progress(0,1)}<div style="margin:18px 0">${button('Créer mon premier objectif','goal','plus')}</div>`}<div class="tip-card">${I('spark')}<span>${q.income?'Votre capacité d’épargne estimée, après les dépenses engagées et votre marge de sécurité : <strong>'+money(q.capacity)+'</strong>.':'Ajoutez vos revenus et vos dépenses pour obtenir une estimation adaptée à votre situation.'}</span></div></section><section class="panel wide"><div class="panel-head"><div><h2>Vos derniers mouvements</h2><p class="panel-sub">${monthName()} · chaque mouvement compte</p></div><button class="text-btn" data-page="expense">Tout consulter ${I('arrow')}</button></div>${transactionTable(q.tx.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))}</section><section class="panel"><div class="panel-head"><div><h2>Votre rythme de dépenses</h2><p class="panel-sub">Cumul des dépenses payées pendant le mois</p></div></div>${lineChart(q)}</section><section class="panel"><div class="panel-head"><div><h2>Les 5 premiers postes</h2><p class="panel-sub">Payés et prévus, du plus grand au plus petit</p></div></div>${topCategories(q)}</section></div>`}
function chartEmpty(text='Vos chiffres raconteront bientôt une histoire.'){return `<div class="chart-empty"><div class="empty-icon">${I('chart')}</div><p>${text}</p><small>Ajoutez un mouvement pour faire apparaître ce graphique.</small></div>`}
function barsChart(){const months=comparison==='year'?Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`):Array.from({length:6},(_,i)=>F.shift(month,i-5));const values=months.map(m=>F.metrics(S,m));const max=Math.max(...values.flatMap(q=>[q.income,q.spent,q.saved]),0);if(!max)return chartEmpty();const w=620,h=225,chartH=175,step=560/months.length,bw=Math.min(17,step/5);let svg='';for(let n=0;n<=4;n++){let y=12+n*chartH/4;svg+=`<line class="gridline" x1="48" x2="615" y1="${y}" y2="${y}"/><text x="39" y="${y+3}" text-anchor="end">${esc(new Intl.NumberFormat('fr-FR',{notation:'compact',maximumFractionDigits:0}).format(max*(4-n)/4/100))}</text>`}values.forEach((q,i)=>{const x=54+i*step+step/2-bw*1.9;[q.income,q.spent,q.saved].forEach((v,k)=>{const bh=v/max*chartH;const title=monthName(months[i])+' · '+['Revenus','Dépenses','Épargne'][k]+' : '+money(v);svg+=`<rect x="${x+k*(bw+3)}" y="${12+chartH-bh}" width="${bw}" height="${Math.max(bh,1)}" rx="3" fill="${['#4d7359','#b8c9a0','#e4bd7e'][k]}" data-tip="${esc(title)}"><title>${esc(title)}</title></rect>`});svg+=`<text x="${54+i*step+step/2}" y="211" text-anchor="middle">${esc(new Date(months[i]+'-02').toLocaleDateString('fr-FR',{month:'short',timeZone:'UTC'}))}</text>`});return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Comparaison des revenus, dépenses et versements d’épargne mensuels">${svg}</svg>`}
function donutChart(q){const cats=q.byCategory.filter(c=>c.paid>0).sort((a,b)=>b.paid-a.paid);let offset=0;const circles=cats.map(c=>{let percent=c.paid/q.spent*100;let t=`<circle cx="100" cy="100" r="78" fill="none" stroke="${c.color}" stroke-width="22" stroke-dasharray="${percent*4.9} ${490-percent*4.9}" stroke-dashoffset="${-offset*4.9}" data-tip="${esc(c.name+' : '+money(c.paid)+' ('+pct(percent)+')')}"><title>${esc(c.name+' : '+money(c.paid))}</title></circle>`;offset+=percent;return t}).join('');return `<div class="donut-layout"><div class="donut"><svg viewBox="0 0 200 200" role="img" aria-label="Répartition des dépenses payées"><circle cx="100" cy="100" r="78" fill="none" stroke="var(--pale)" stroke-width="22"/>${circles}</svg><div class="donut-center"><small>Total dépensé</small><span class="number">${esc(new Intl.NumberFormat('fr-FR',{notation:q.spent>100000000?'compact':'standard',maximumFractionDigits:0}).format(q.spent/100))}</span><small>${S.settings.currency==='XOF'||S.settings.currency==='XAF'?'FCFA':S.settings.currency}</small></div></div><div class="donut-legend">${cats.length?cats.slice(0,5).map(c=>`<button data-cat-filter="${esc(c.id)}"><i class="dot" style="background:${c.color}"></i><span>${esc(c.name)}</span><b>${pct(c.paid/q.spent*100)}</b></button>`).join('')+(cats.length>5?`<span class="small muted">+ ${cats.length-5} autres catégories</span>`:''):`<p class="small muted">Vos catégories apparaîtront ici dès votre première dépense.</p>`}</div></div>`}
function lineChart(q){const n=F.days(month),list=Array.from({length:n},(_,i)=>F.sum(q.paid.filter(t=>t.kind==='expense'&&+t.date.slice(8)<=i+1)));let max=Math.max(...list);if(!max)return chartEmpty('Suivez votre rythme, jour après jour.');const pts=list.map((v,i)=>`${43+i/(n-1)*540},${178-v/max*150}`);return `<svg class="chart-svg" viewBox="0 0 610 215" role="img" aria-label="Cumul quotidien des dépenses payées"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#9bb787" stop-opacity=".25"/><stop offset="1" stop-color="#9bb787" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line class="gridline" x1="43" x2="583" y1="${28+i*50}" y2="${28+i*50}"/><text x="35" y="${31+i*50}" text-anchor="end">${new Intl.NumberFormat('fr-FR',{notation:'compact',maximumFractionDigits:0}).format(max*(3-i)/3/100)}</text>`).join('')}<path d="M43 178 L${pts.join(' L')} L583 178Z" fill="url(#area)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#739765" stroke-width="2.5"/>${list.map((v,i)=>`<circle cx="${43+i/(n-1)*540}" cy="${178-v/max*150}" r="4" fill="#739765" opacity=".02" data-tip="${esc((i+1)+' '+monthName()+' : '+money(v))}"/>`).join('')}${[1,Math.round(n/4),Math.round(n/2),Math.round(n*.75),n].map(i=>`<text x="${43+(i-1)/(n-1)*540}" y="205" text-anchor="middle">${i}</text>`).join('')}</svg>`}
function budgetOverview(q){const percent=q.totalBudget?q.committed/q.totalBudget*100:0;return `<div class="budget-label"><span>Budget mensuel</span><b>${money(q.committed)} <span class="muted">/ ${money(q.totalBudget)}</span></b></div>${progress(q.committed,q.totalBudget)}<div class="budget-meta"><span>${q.totalBudget?pct(percent)+' utilisé':'Budget à définir'}</span><span class="${q.remaining<0?'negative':''}">${q.remaining<0?'Dépassement : '+money(-q.remaining):money(q.remaining)+' restants'}</span></div><div style="height:23px"></div>${q.byCategory.filter(c=>c.limit).slice(0,3).map(c=>`<div class="budget-row"><div class="budget-label"><span><i class="dot" style="background:${c.color}"></i>${esc(c.name)}</span><b>${money(c.spent)} <span class="muted">/ ${money(c.limit)}</span></b></div>${progress(c.spent,c.limit)}</div>`).join('')||`<div class="tip-card">${I('wallet')}<span>Fixez vos limites par catégorie pour suivre votre budget au quotidien.</span></div>`}`}
function miniGoal(g){const value=F.goalValue(S,g,month);return `<div class="project-card"><div class="project-icon">${I(g.icon||'goal')}</div><div class="project-info"><p>${esc(g.name)}</p>${progress(value,g.target)}<div class="goal-numbers"><small>${money(value)} <span>/ ${money(g.target)}</span></small><b>${pct(Math.min(100,value/g.target*100))}</b></div></div></div>`}
function topCategories(q){const list=q.byCategory.filter(c=>c.spent).slice(0,5),max=Math.max(...list.map(c=>c.spent),1);return list.length?list.map((c,i)=>`<div class="budget-row"><div class="budget-label"><span><span class="muted small">0${i+1}</span> &nbsp; ${esc(c.name)}</span><b>${money(c.spent)}</b></div><div class="progress" style="height:5px"><span style="width:${c.spent/max*100}%;background:${c.color}"></span></div></div>`).join(''):chartEmpty('Vos priorités se dessineront ici.')}
function transactionTable(txs){return txs.length?`<div class="table-scroll"><table class="transaction-table"><thead><tr><th>Mouvement</th><th>Date</th><th>Catégorie / source</th><th>Statut</th><th style="text-align:right">Montant</th><th><span class="muted">Actions</span></th></tr></thead><tbody>${txs.map(t=>`<tr><td><div class="row-desc"><span class="tx-icon">${I(t.kind==='expense'?cat(t.category)?.icon:t.kind==='saving'?'goal':t.kind==='transfer'?'transfer':'income')}</span><div>${esc(t.description)}<span class="row-sub">${kindNames[t.kind]} · ${typeNames[t.type]}${t.frequency!=='once'?' · '+freqNames[t.frequency]:''}</span></div></div></td><td>${dateName(t.date)}</td><td class="muted">${esc(t.kind==='expense'?(cat(t.category)?.name||'Catégorie supprimée')+(t.sub?' · '+t.sub:''):t.kind==='income'?t.source||'Autres revenus':t.kind==='saving'?S.goals.find(g=>g.id===t.goal)?.name||'Épargne libre':'Entre mes comptes')}</td><td><span class="status ${t.status}">${t.status==='planned'?'Prévu':t.kind==='income'?'Reçu':t.kind==='expense'?'Payée':'Effectué'}</span></td><td class="amount ${t.kind==='income'?'positive':''}">${t.kind==='income'?'+':t.kind==='transfer'?'↔':'−'} ${money(t.amount)}</td><td><div class="row-actions">${t.status==='planned'?`<button data-pay="${esc(t.id)}" aria-label="Valider ${esc(t.description)}" title="Marquer comme effectué">${I('check')}</button>`:''}<button data-edit="${esc(t.id)}" aria-label="Modifier ${esc(t.description)}">${I('edit')}</button><button data-delete="${esc(t.id)}" aria-label="Supprimer ${esc(t.description)}">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-table"><p>Aucun mouvement pour le moment</p><small>Ajoutez votre premier mouvement ou ajustez vos filtres.</small></div>`}
function filtered(kind){return F.metrics(S,month).tx.filter(t=>(!kind||t.kind===kind)&&(!filters.q||[t.description,t.source,t.payment,t.sub,cat(t.category)?.name||'',t.amount/100].join(' ').toLocaleLowerCase('fr').includes(filters.q.toLocaleLowerCase('fr')))&&(!filters.category||t.category===filters.category)&&(!filters.status||t.status===filters.status)&&(!filters.nature||t.type===filters.nature)&&(!filters.source||t.source===filters.source)).sort((a,b)=>b.date.localeCompare(a.date))}
function transactionPage(kind){const q=F.metrics(S,month);return `<div class="stats">${kind==='income'?stat('Revenus reçus',q.income,'income',money(q.expected)+' attendus')+stat('Revenus fixes',q.fixed,'lock','Revenus reçus de nature fixe')+stat('Revenus variables',q.variable,'chart',incomeTrend(q)):stat('Dépenses payées',q.spent,'expense','Sorties effectives du mois')+stat('Dépenses prévues',q.planned,'calendar','À anticiper dans votre solde')+stat('Total engagé',q.committed,'wallet','Payé + prévu, sans double compte')}</div><section class="panel"><div class="panel-head"><div><h2>${kind==='income'?'Mes sources de revenus':'Historique de mes dépenses'}</h2><p class="panel-sub">${kind==='income'?'Les revenus attendus restent séparés des revenus reçus.':'Filtrez, recherchez et modifiez chaque dépense.'}</p></div><div class="button-row">${button('CSV','csv','down')}${button('Récurrences','recurring','refresh')}</div></div><div class="toolbar"><input type="search" id="search" placeholder="Rechercher un libellé, un montant…" aria-label="Rechercher des mouvements" value="${esc(filters.q)}">${kind==='expense'?`<select id="category-filter" aria-label="Filtrer par catégorie"><option value="">Toutes les catégories</option>${S.categories.map(c=>`<option value="${esc(c.id)}" ${filters.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:`<select id="source-filter" aria-label="Filtrer par source"><option value="">Toutes les sources</option>${incomeSources.map(c=>`<option ${filters.source===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`}<select id="status-filter" aria-label="Filtrer par statut"><option value="">Tous les statuts</option><option value="paid" ${filters.status==='paid'?'selected':''}>${kind==='income'?'Reçu':'Payée'}</option><option value="planned" ${filters.status==='planned'?'selected':''}>Prévu</option></select><select id="nature-filter" aria-label="Filtrer par nature"><option value="">Toutes les natures</option>${Object.entries(typeNames).map(([k,v])=>`<option value="${k}" ${filters.nature===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="tx-list">${transactionTable(filtered(kind))}</div><div id="tx-count" class="small muted" style="margin-top:14px">${filtered(kind).length} mouvement(s) · Total filtré : ${money(F.sum(filtered(kind)))}</div></section>${kind==='expense'?`<div class="section-grid" style="margin-top:20px"><section class="panel"><h2>Dépenses par jour et par semaine</h2><p class="panel-sub">Payées uniquement · semaines du lundi au dimanche</p><div class="table-scroll" style="max-height:330px;margin-top:18px"><table class="simulation-table"><thead><tr><th>Date</th><th>Semaine commençant le</th><th>Dépenses payées</th></tr></thead><tbody>${dailyRows(q)}</tbody></table></div></section><section class="panel"><h2>Les mouvements qui ne sont pas des dépenses</h2><p class="panel-sub">Versements d’épargne et transferts internes du mois</p><div style="margin:18px 0" class="button-row">${button('Verser à mon épargne','add-saving','plus')}${button('Transfert interne','add-transfer','transfer')}</div>${transactionTable(q.tx.filter(t=>t.kind==='saving'||t.kind==='transfer'))}</section></div>`:''}`}
function incomeTrend(q){const p=F.metrics(S,F.shift(month,-1));return p.income?(q.income>=p.income?'+':'')+pct((q.income-p.income)/p.income*100)+' par rapport au mois précédent':'Comparaison disponible avec deux mois renseignés'}
function dailyRows(q){const dates=[...new Set(q.paid.filter(t=>t.kind==='expense').map(t=>t.date))].sort();const weeks={};for(const d of dates){const dt=new Date(d+'T00:00:00Z');dt.setUTCDate(dt.getUTCDate()-(dt.getUTCDay()+6)%7);const k=dt.toISOString().slice(0,10);weeks[k]=(weeks[k]||0)+F.sum(q.paid.filter(t=>t.kind==='expense'&&t.date===d))}return dates.map(d=>{const dt=new Date(d+'T00:00:00Z');dt.setUTCDate(dt.getUTCDate()-(dt.getUTCDay()+6)%7);const k=dt.toISOString().slice(0,10);return `<tr><td>${dateName(d)}</td><td>${dateName(k)} · ${money(weeks[k])}</td><td>${money(F.sum(q.paid.filter(t=>t.kind==='expense'&&t.date===d)))}</td></tr>`}).join('')||'<tr><td colspan="3">Aucune dépense payée ce mois-ci.</td></tr>'}
function budgetPage(q){const b=S.budgets[month];return `<div class="section-intro">${I('wallet')}<div><h3>Un cadre souple, adapté à votre quotidien</h3><p>Les dépenses prévues réservent aussi une part du budget. Les versements d’épargne sont suivis séparément.</p></div></div><section class="panel"><form id="budget-form"><div class="panel-head"><div><h2>Mon enveloppe de ${monthName()}</h2><p class="panel-sub">Les limites sont conservées pour chaque mois.</p></div>${button('Reprendre le mois précédent','copy-budget','refresh')}</div><div class="form-grid" style="margin-bottom:25px"><label class="field">Budget mensuel total (${S.settings.currency})<input name="total" type="text" inputmode="decimal" value="${numInput(b.total)}" required><small>Ce total fait foi. Les limites par catégorie sont des enveloppes de répartition.</small></label><div><div class="budget-label"><span>${money(q.committed)} engagés</span><b>${b.total?pct(q.committed/b.total*100):'À définir'}</b></div>${progress(q.committed,b.total)}<p class="small ${q.remaining<0?'negative':'muted'}" style="margin-top:10px">${q.remaining<0?'Dépassement de '+money(-q.remaining):money(q.remaining)+' disponibles dans le budget'}</p></div></div><div class="table-scroll"><table class="budget-table"><thead><tr><th>Catégorie</th><th>Budget prévu</th><th>Payé + prévu</th><th>Restant</th><th>Utilisation</th></tr></thead><tbody>${S.categories.map(c=>{const a=q.byCategory.find(a=>a.id===c.id),l=b.limits[c.id]||0;return `<tr><td><i class="dot" style="background:${c.color}"></i>${esc(c.name)}</td><td><input aria-label="Budget ${esc(c.name)}" type="text" inputmode="decimal" name="limit-${esc(c.id)}" value="${numInput(l)}"></td><td>${money(a.spent)}<small class="row-sub">dont ${money(a.paid)} payés</small></td><td class="${l&&a.spent>l?'negative':'muted'}">${l?money(l-a.spent):'Sans limite'}</td><td>${l?progress(a.spent,l)+`<span class="small ${a.spent>l?'negative':''}">${pct(a.spent/l*100)}${a.spent>l?' · dépassé':''}</span>`:'—'}</td></tr>`}).join('')}</tbody></table></div><div class="notice">Somme des enveloppes : ${money(Object.values(b.limits).reduce((a,n)=>a+n,0))}. ${Object.values(b.limits).reduce((a,n)=>a+n,0)>b.total?'La répartition dépasse le budget total. Ajustez vos enveloppes.':'Vous pouvez conserver une part non affectée.'}</div><div id="form-error" class="notice error" role="alert"></div><div class="form-actions">${button('Gérer mes catégories','categories','settings')}<button type="submit" class="btn primary">${I('check')}Enregistrer le budget</button></div></form></section><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Le repère 50 / 30 / 20</h2><p class="panel-sub">Un point de comparaison facultatif, jamais une obligation.</p></div><label class="check"><input id="framework" type="checkbox" ${S.settings.framework?'checked':''}>Afficher le repère</label></div>${S.settings.framework?`<div class="fifty"><span style="width:50%;background:#55795d"></span><span style="width:30%;background:#b8c9a0"></span><span style="width:20%;background:#e4bd7e"></span></div><div class="section-grid">${[['Besoins essentiels',.5,q.essentials],['Envies et loisirs',.3,q.byCategory.filter(c=>c.group==='want').reduce((a,c)=>a+c.spent,0)],['Épargne et objectifs',.2,q.saved]].map(([n,p,a])=>`<div class="stat-row"><span>${p*100} % · ${n}<small class="row-sub">Repère : ${money(q.income*p)}</small></span><b>${money(a)}<small class="row-sub">Réel${n==='Épargne et objectifs'?'':' + prévu'}</small></b></div>`).join('')}</div><p class="notice">La classification « besoins » ou « envies » est modifiable dans les catégories. Priorisez vos dépenses essentielles et votre stabilité. Les pourcentages ne déclenchent aucune opération.</p>`:'<p class="small muted">Activez ce repère pour comparer votre répartition à 50 % de besoins, 30 % d’envies et 20 % d’épargne, sur vos revenus reçus.</p>'}</section>`}
function savingPage(q){return `<section class="stats">${stat('Versements du mois',q.saved,'goal','Épargne libre et objectifs inclus')}${stat('Épargne déclarée',q.reserve,'shield','Solde initial + versements cumulés')}${stat('Capacité estimée du mois',q.capacity,'spark','Après dépenses engagées et sécurité')}</section><div class="section-grid"><section class="panel"><h2>Mon rythme d’épargne</h2><p class="panel-sub">Une intention réaliste, à ajuster selon votre situation.</p><form id="saving-settings" style="margin-top:22px"><div class="form-grid"><label class="field">Objectif mensuel (${S.settings.currency})<input name="monthlyGoal" type="text" inputmode="decimal" value="${numInput(S.settings.monthlyGoal)}" required></label><label class="field">Pourcentage du salaire principal reçu<input name="salaryPercent" type="number" min="0" max="100" step="0.1" value="${S.settings.salaryPercent}" required><small>Repère utilisé si l’objectif mensuel est nul.</small></label><label class="field">Objectif annuel (${S.settings.currency})<input name="annualGoal" type="text" inputmode="decimal" value="${numInput(S.settings.annualGoal)}" required></label><label class="field">Marge de sécurité à préserver<input name="buffer" type="text" inputmode="decimal" value="${numInput(S.settings.buffer)}" required></label></div><div class="notice">Estimation prudente : ${money(q.recommended)} pour le mois, en tenant compte de vos revenus reçus, des dépenses engagées et de votre marge de sécurité. Aucun transfert automatique.</div><div class="notice error" id="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Enregistrer</button>${button('Enregistrer un versement','add-saving','plus')}</div></form></section><section class="panel"><div class="panel-head"><div><h2>Une épargne qui avance</h2><p class="panel-sub">Objectif du mois</p></div><span class="badge">${S.settings.monthlyGoal?pct(q.saved/S.settings.monthlyGoal*100):'À définir'}</span></div><div class="metric-inline">${money(q.saved)} <span class="small muted">/ ${money(S.settings.monthlyGoal)}</span></div>${progress(q.saved,S.settings.monthlyGoal)}<div class="budget-meta"><span>Réellement versé</span><span>Reste : ${money(Math.max(0,S.settings.monthlyGoal-q.saved))}</span></div><div style="height:22px"></div><h3>Projection à rythme constant</h3><p class="panel-sub">Hypothèse : ${money(q.saved)} versés par mois, sans rendement, sans retrait.</p><table class="simulation-table"><thead><tr><th>Horizon</th><th>Épargne déclarée projetée</th></tr></thead><tbody>${[3,6,12].map(n=>`<tr><td>Dans ${n} mois</td><td>${money(q.reserve+n*q.saved)}</td></tr>`).join('')}</tbody></table><p class="small muted" style="margin-top:14px">Projection indicative. L’épargne déclarée inclut votre montant initial et les versements enregistrés jusqu’à la fin du mois sélectionné. Les montants initiaux des objectifs sont suivis séparément et ne s’y ajoutent pas.</p></section><section class="panel span2"><div class="panel-head"><div><h2>Mes objectifs financiers</h2><p class="panel-sub">Chaque projet mérite son propre chemin.</p></div>${button('Nouvel objectif','goal','plus')}</div><div class="section-grid">${S.goals.length?S.goals.map(g=>{let v=F.goalValue(S,g,month),remain=Math.max(0,g.target-v),monthly=F.sum(q.paid.filter(t=>t.kind==='saving'&&t.goal===g.id));let remainingMonths=g.deadline?Math.max(0,(+g.deadline.slice(0,4)- +month.slice(0,4))*12 + +g.deadline.slice(5,7)- +month.slice(5,7)):0;return `<article class="panel goal-card"><div class="project-icon">${I(g.icon||'goal')}</div><div class="row-actions"><button data-edit-goal="${esc(g.id)}" aria-label="Modifier ${esc(g.name)}">${I('edit')}</button><button data-delete-goal="${esc(g.id)}" aria-label="Supprimer ${esc(g.name)}">${I('trash')}</button></div><h3>${esc(g.name)}</h3><p>${g.deadline?'Échéance : '+new Date(g.deadline+'T00:00:00Z').toLocaleDateString('fr-FR',{timeZone:'UTC'}):'À votre rythme'}</p><div class="metric-inline">${money(v)} <span class="small muted">/ ${money(g.target)}</span></div>${progress(v,g.target)}<div class="budget-meta"><span>${pct(Math.min(100,v/g.target*100))} atteint</span><span>${money(remain)} restants</span></div><div class="notice">${remain===0?'Objectif atteint. Prenez un instant pour savourer ce progrès.':monthly?Math.ceil(remain/monthly)+' mois estimés au rythme de '+money(monthly)+' par mois.':'Ajoutez un versement lié à cet objectif pour estimer sa durée.'}${g.deadline&&remain?' Pour l’échéance : '+(remainingMonths?money(Math.ceil(remain/remainingMonths))+' par mois environ.':'échéance ce mois-ci ou dépassée.') :''}</div><button class="btn" data-contribute="${esc(g.id)}">${I('plus')}Ajouter un versement</button></article>`}).join(''):`<div class="empty-table span2"><p>Un projet commence par une intention.</p><small>Créez un fonds d’urgence, un achat ou un projet personnel.</small></div>`}</div></section><section class="panel span2"><h2>Mes versements d’épargne</h2><p class="panel-sub" style="margin-bottom:18px">Ils diminuent le solde courant et augmentent l’épargne. Ils ne sont jamais comptés comme dépenses.</p>${transactionTable(q.tx.filter(t=>t.kind==='saving'))}</section></div>`}
function observations(q){const p=F.metrics(S,F.shift(month,-1));if(!q.tx.length)return [{tag:'À compléter',title:'Votre analyse commence avec vos données',text:'Ajoutez vos revenus reçus, vos dépenses payées et vos prochaines factures. Les constats et estimations seront alors calculés pour le mois sélectionné.'}];const largest=q.byCategory.find(c=>c.spent);const out=[{tag:'Constat calculé',title:'Votre mois en trois chiffres',text:`Vous avez reçu ${money(q.income)}, payé ${money(q.spent)} de dépenses et versé ${money(q.saved)} à votre épargne. ${money(q.expected)} de revenus restent attendus. Votre solde courant après mouvements est de ${money(q.cash)} ; après les mouvements prévus, ${money(q.available)} restent disponibles.`}];
 if(largest)out.push({tag:'Constat calculé',title:largest.name+' est votre premier poste',text:`Cette catégorie représente ${money(largest.spent)}, soit ${pct(q.committed?largest.spent/q.committed*100:0)} de vos dépenses payées et prévues. ${largest.limit?'Son enveloppe est de '+money(largest.limit)+'.':'Aucune limite n’est définie pour cette catégorie.'}`});
 out.push({tag:'Constat calculé',title:q.totalBudget?(q.remaining<0?'Votre budget est dépassé':'Votre budget garde de la marge'):'Votre budget reste à définir',text:q.totalBudget?(q.remaining<0?`Vos dépenses engagées dépassent votre budget de ${money(-q.remaining)}. Revoyez d’abord les achats encore prévus.`:`Il reste ${money(q.remaining)} dans votre enveloppe, après les dépenses payées et prévues.`):'Définissez un budget mensuel et des limites par catégorie pour détecter les dépassements.'});
 out.push({tag:'Estimation',title:'Une capacité d’épargne prudente',text:`Votre capacité totale du mois est estimée à ${money(q.capacity)}, avant prise en compte de vos versements d’épargne déjà effectués. Selon votre objectif, le montant indicatif est de ${money(q.recommended)} ; vous avez déjà versé ${money(q.saved)}. Calcul : revenus reçus moins toutes les dépenses engagées et votre marge de sécurité de ${money(S.settings.buffer)}, plafonné par le solde disponible avant épargne du mois. Les revenus attendus ne sont pas utilisés.`});
 if(p.tx.length){const d=q.surplus-p.surplus;out.push({tag:'Comparaison calculée',title:d>=0?'Votre marge mensuelle a progressé':'Votre marge mensuelle a diminué',text:`La différence revenus reçus − dépenses payées est de ${money(q.surplus)}, contre ${money(p.surplus)} le mois précédent, soit ${d>=0?'+':''}${money(d)}. Cette comparaison porte sur les mois saisis, qui peuvent être incomplets.`})}
 if(q.available<0||q.committed>q.income)out.push({tag:'Point à surveiller',title:'Préservez vos dépenses essentielles',text:`${q.available<0?'Votre solde disponible est négatif de '+money(-q.available)+'. ':''}${q.committed>q.income?'Vos dépenses engagées dépassent vos revenus reçus de '+money(q.committed-q.income)+'. ':''}Vérifiez les revenus en attente et reportez si possible un achat non essentiel avant d’augmenter votre épargne.`});
 const wants=q.byCategory.filter(c=>c.group==='want'&&c.spent>0);if(wants.length){const w=wants.reduce((a,c)=>a+c.spent,0);out.push({tag:'Suggestion facultative',title:'Un levier dans vos envies et loisirs',text:`Vous engagez ${money(w)} dans ${wants.map(c=>c.name).join(', ')}. Une réduction volontaire de 10 % libérerait environ ${money(Math.round(w*.1))}. Ce scénario suppose que ces dépenses peuvent réellement être réduites.`})}
 const recur=q.tx.filter(t=>t.kind==='expense'&&t.frequency!=='once');if(recur.length)out.push({tag:'À vérifier',title:'Passez vos paiements récurrents en revue',text:`${recur.length} paiement(s) récurrent(s), pour ${money(F.sum(recur))} ce mois-ci : ${recur.slice(0,4).map(t=>t.description).join(', ')}. Vérifiez leur utilité avant de renouveler. L’application ne peut pas déterminer si un service vous est inutile.`});
 const high=q.tx.filter(t=>t.kind==='expense'&&t.amount>q.income*.2&&q.income>0);if(high.length)out.push({tag:'Seuil explicite',title:'Des dépenses importantes à anticiper',text:`${high.map(t=>t.description+' ('+money(t.amount)+')').join(', ')} représentent chacune plus de 20 % des revenus reçus du mois. Ce seuil signale un montant important, sans conclure à une anomalie.`});return out}
function healthPanel(){const h=F.health(S,month);return `<h2>Mon équilibre financier</h2><p class="panel-sub">Quatre critères visibles, sans score opaque.</p><div class="health-score"><div class="score-ring">${h.score===null?'—':h.score+'/4'}</div><div><h3>${h.label}</h3><p class="panel-sub">${h.score===null?'Renseignez vos premiers mouvements.':'Critères remplis pour le mois sélectionné'}</p></div></div><div class="health-list">${h.items.map(i=>`<div class="health-item ${i.ok?'ok':''}">${I(i.ok?'check':'info')}<div>${i.name}<small>${i.detail}</small></div></div>`).join('')}</div><p class="notice">Repères descriptifs calculés uniquement sur les données saisies. La réserve représente l’épargne déclarée, pas une vérification de vos comptes. La catégorie « Obligations financières » sert de proxy large aux engagements.</p>`}
function analysisPage(q){return `<div class="section-grid"><section class="panel"><h2>Ce que vos chiffres vous disent</h2><p class="panel-sub" style="margin-bottom:20px">${monthName()} · actualisation à chaque modification</p><div class="analysis-list">${observations(q).map(o=>`<article class="analysis-item"><span class="badge ${o.tag==='Point à surveiller'?'red':''}">${o.tag}</span><h3>${esc(o.title)}</h3><p>${esc(o.text)}</p></article>`).join('')}</div></section><div class="stack"><section class="panel">${healthPanel()}</section><section class="panel"><div class="panel-head"><div><h2>Évolution financière</h2><p class="panel-sub">Comparaison mensuelle ou annuelle</p></div><select id="comparison-year" class="chart-year-select" aria-label="Année comparée">${Array.from({length:10},(_,i)=>+month.slice(0,4)-5+i).map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></div><div class="annual-switch"><button data-comparison="six" class="${comparison==='six'?'active':''}">6 mois</button><button data-comparison="year" class="${comparison==='year'?'active':''}">12 mois de l’année</button></div><div style="margin-top:20px">${barsChart()}</div><div class="chart-legend"><span><i class="dot" style="background:#4d7359"></i>Revenus</span><span><i class="dot" style="background:#b8c9a0"></i>Dépenses</span><span><i class="dot" style="background:#e4bd7e"></i>Épargne</span></div>${annualComparison()}</section><section class="panel"><h2>Comment sont calculés vos chiffres ?</h2><div class="notice">Solde courant = montant courant initial + revenus reçus − dépenses payées − versements d’épargne, cumulés depuis la date initiale jusqu’à la fin du mois. Solde disponible = solde courant − dépenses et versements prévus du mois. Épargne du mois = versements effectués. Budget restant = budget − dépenses payées et prévues. Les transferts entre vos comptes sont neutres.</div></section></div></div>`}
function annualComparison(){const totals=y=>{let list=Array.from({length:12},(_,i)=>F.metrics(S,y+'-'+String(i+1).padStart(2,'0')));return {income:list.reduce((a,q)=>a+q.income,0),spent:list.reduce((a,q)=>a+q.spent,0),saved:list.reduce((a,q)=>a+q.saved,0)}};const a=totals(year),b=totals(year-1);return `<table class="simulation-table" style="margin-top:20px"><thead><tr><th>Année</th><th>Revenus</th><th>Dépenses</th><th>Épargne</th></tr></thead><tbody>${[[year,a],[year-1,b]].map(([y,t])=>`<tr><td>${y}</td><td>${money(t.income,true)}</td><td>${money(t.spent,true)}</td><td>${money(t.saved,true)}</td></tr>`).join('')}</tbody></table><p class="panel-sub">Totaux des seules données saisies, y compris les mois incomplets.</p>`}
function simulatorPage(q){return `<div class="section-intro">${I('sliders')}<div><h3>Et si vous faisiez un petit changement ?</h3><p>Ces simulations ne modifient jamais vos mouvements ni votre budget.</p></div></div><div class="section-grid"><section class="panel"><h2>Mes hypothèses</h2><p class="panel-sub">Base : revenus reçus et dépenses payées ou prévues du mois.</p><div style="margin-top:25px"><div class="range-field"><div class="range-label"><label for="sim-raise">Hausse du salaire principal</label><output id="raise-output">${pct(simulation.raise)}</output></div><input id="sim-raise" type="range" min="0" max="100" step="1" value="${simulation.raise}"></div><div class="range-field"><div class="range-label"><label for="sim-cut">Réduction de toutes les dépenses</label><output id="cut-output">${pct(simulation.cut)}</output></div><input id="sim-cut" type="range" min="0" max="50" step="1" value="${simulation.cut}"><div class="button-row" style="margin-top:10px">${[10,15,20].map(n=>`<button class="btn" data-cut="${n}">${n} %</button>`).join('')}</div></div><div class="form-grid">${[['extra','Revenu mensuel supplémentaire'],['saving','Épargne mensuelle envisagée'],['target','Objectif à financer'],['purchase','Achat ponctuel envisagé']].map(([k,l])=>`<label class="field">${l} (${S.settings.currency})<input id="sim-${k}" inputmode="decimal" type="text" value="${numInput(simulation[k])}" required></label>`).join('')}</div><div id="sim-error" class="notice error" role="alert"></div></div><div class="notice">Hypothèses : revenus constants, réduction identique appliquée à toutes les dépenses, aucun rendement ni inflation. La hausse concerne uniquement les revenus reçus dont la source est « Salaire principal (net) ». L’épargne future et l’achat sont distincts des dépenses de base.</div></section><section class="panel"><h2>Ce que cela pourrait changer</h2><p class="panel-sub">Estimations indicatives, sans garantie de résultat.</p><div id="simulation-results" style="margin-top:22px">${simulationResults(q)}</div></section></div>`}
function simulationResults(q){const salary=F.sum(q.paid.filter(t=>t.kind==='income'&&t.source==='Salaire principal (net)'));const gain=Math.round(salary*simulation.raise/100)+simulation.extra;const spending=Math.round(q.committed*(1-simulation.cut/100));const revenues=q.income+gain;const capacity=revenues-spending-S.settings.buffer;const liquid=q.available+gain+(q.committed-spending)-simulation.purchase;const budgetLeft=q.totalBudget-spending-simulation.purchase;const reserveAfterSaving=capacity-simulation.saving;return `<div class="simulation-result"><span class="small">Marge mensuelle estimée, avant nouvelle épargne</span><div class="number ${capacity<0?'negative':''}">${money(capacity)}</div><small>Après dépenses simulées et marge de sécurité de ${money(S.settings.buffer)}.</small></div><table class="simulation-table"><thead><tr><th>Indicateur</th><th>Situation saisie</th><th>Scénario</th></tr></thead><tbody><tr><td>Revenus</td><td>${money(q.income)}</td><td>${money(revenues)}</td></tr><tr><td>Dépenses engagées</td><td>${money(q.committed)}</td><td>${money(spending)}</td></tr><tr><td>Épargne envisagée</td><td>${money(q.saved)}</td><td>${money(simulation.saving)}</td></tr><tr><td>Marge après épargne envisagée</td><td>—</td><td class="${reserveAfterSaving<0?'negative':'positive'}">${money(reserveAfterSaving)}</td></tr></tbody></table><div class="notice">${simulation.target?(simulation.saving?`Pour financer ${money(simulation.target)} à partir de zéro : environ ${Math.ceil(simulation.target/simulation.saving)} mois, avec ${money(simulation.saving)} par mois. ${simulation.saving>Math.max(0,capacity)?'Ce versement dépasse la capacité du scénario.':''}`:'Indiquez une épargne mensuelle positive pour estimer la durée de votre objectif.'):'Renseignez un objectif à financer pour calculer sa durée.'}</div>${simulation.purchase?`<div class="tip-card">${I('wallet')}<span>${!q.totalBudget?'Définissez un budget pour évaluer cet achat.':budgetLeft>=0&&liquid-simulation.saving>=S.settings.buffer?`L’achat de ${money(simulation.purchase)} entre dans le budget simulé. Reste dans le budget : ${money(budgetLeft)}. Solde estimé après achat et nouvelle épargne : ${money(liquid-simulation.saving)}.`:`L’achat de ${money(simulation.purchase)} ${budgetLeft<0?'dépasserait le budget de '+money(-budgetLeft):'ne préserverait pas la marge de sécurité après nouvelle épargne'}. Solde simulé après achat et nouvelle épargne : ${money(liquid-simulation.saving)}.`}</span></div>`:''}<h3 style="margin-top:23px">Épargne projetée à rythme constant</h3><p class="panel-sub">À partir de l’épargne déclarée de ${money(q.reserve)}, sans retrait ni rendement.</p>${projectionChart(q.reserve,simulation.saving)}<table class="simulation-table"><thead><tr><th>Dans 3 mois</th><th>Dans 6 mois</th><th>Dans 12 mois</th></tr></thead><tbody><tr>${[3,6,12].map(n=>`<td>${money(q.reserve+n*simulation.saving)}</td>`).join('')}</tr></tbody></table>`}
function projectionChart(base,saving){const max=Math.max(base+12*saving,1);const pts=[0,3,6,12].map((n,i)=>`${45+i*155},${145-(base+n*saving)/max*115}`);return `<svg class="chart-svg" style="margin-top:12px" viewBox="0 0 550 180" role="img" aria-label="Projection de l’épargne à 3, 6 et 12 mois"><line x1="45" x2="510" y1="145" y2="145" class="gridline"/><polyline points="${pts.join(' ')}" fill="none" stroke="#829f6e" stroke-width="3"/>${[0,3,6,12].map((n,i)=>`<circle cx="${45+i*155}" cy="${145-(base+n*saving)/max*115}" r="5" fill="#829f6e" data-tip="${esc((n?n+' mois':'Aujourd’hui')+' : '+money(base+n*saving))}"/><text x="${45+i*155}" y="170" text-anchor="middle">${n?n+' mois':'Départ'}</text>`).join('')}</svg>`}
function calendarPage(q){const dt=new Date(month+'-01T00:00:00Z'),offset=(dt.getUTCDay()+6)%7;return `<section class="panel"><div class="panel-head"><div><h2 style="text-transform:capitalize">${monthName()}</h2><p class="panel-sub">Sélectionnez un jour pour consulter ou ajouter un mouvement.</p></div>${button('Préparer les récurrences','recurring','refresh')}</div><div class="calendar">${['Lun.','Mar.','Mer.','Jeu.','Ven.','Sam.','Dim.'].map(d=>`<div class="day-name">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="day void"></div>').join('')}${Array.from({length:F.days(month)},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),t=q.tx.filter(t=>t.date===d),goals=S.goals.filter(g=>g.deadline===d);return `<button class="day ${d===F.today()?'is-today':''}" data-day="${d}" aria-label="${i+1} ${monthName()}, ${t.length} mouvement(s)${goals.length?', échéance d’objectif':''}"><span class="day-num">${i+1}</span>${t.slice(0,3).map(t=>`<small style="color:${t.kind==='income'?'var(--green)':t.kind==='expense'?'var(--orange)':'var(--muted)'}" title="${esc(t.description)}">${t.status==='planned'?'◌ ':''}${t.kind==='income'?'+':t.kind==='transfer'?'↔':'−'}${money(t.amount,true)}</small>`).join('')}${t.length>3?`<small>+ ${t.length-3} autre(s)</small>`:''}${goals.map(g=>`<small>⚑ ${esc(g.name)}</small>`).join('')}</button>`}).join('')}</div><div class="calendar-key"><span><i class="dot" style="background:#62835b"></i>Revenus</span><span><i class="dot" style="background:#c59c58"></i>Dépenses</span><span><i class="dot" style="background:#8c9b8c"></i>Épargne / transfert</span><span>◌ Mouvement prévu</span><span>⚑ Échéance d’objectif</span></div></section><div class="notice">Changer de mois conserve l’historique et reprend les enveloppes du dernier mois antérieur. Aucun mouvement n’est dupliqué. Les récurrences sont préparées uniquement avec le bouton ci-dessus, au statut « prévu ».</div>`}
function reportsPage(q){const h=F.health(S,month),prev=F.metrics(S,F.shift(month,-1));const yearSaved=F.sum(S.transactions.filter(t=>t.kind==='saving'&&t.status==='paid'&&t.date.startsWith(month.slice(0,4))&&t.date.slice(0,7)<=month));return `<div class="print-help no-print">Le bouton « Imprimer / PDF » ouvre l’impression du navigateur. Choisissez « Enregistrer au format PDF » pour conserver ce bilan.</div><div class="button-row no-print" style="margin-bottom:23px">${button('Imprimer / PDF','print','print','primary')}${button('Exporter les mouvements CSV','csv','down')}${button('Sauvegarde complète','backup','down')}</div><section class="panel"><div class="report-only"><div class="eyebrow">Budget Perso — Budget, Dépenses & Épargne</div><h1>Mon Bilan Financier du Mois</h1><p>${monthName()}${S.demo?' · Données fictives':''}</p></div><div class="report-kpis"><div>Revenus reçus<strong>${money(q.income)}</strong></div><div>Dépenses payées<strong>${money(q.spent)}</strong></div><div>Épargne versée<strong>${money(q.saved)}</strong></div></div><div class="report-section"><h3>1. Résumé des revenus</h3><p>Revenus reçus : ${money(q.income)}, dont ${money(q.fixed)} fixes et ${money(q.variable)} variables ou exceptionnels. Revenus attendus : ${money(q.expected)}.</p></div><div class="report-section"><h3>2. Résumé des dépenses</h3><p>Dépenses payées : ${money(q.spent)}. Dépenses prévues : ${money(q.planned)}. Total engagé : ${money(q.committed)}. Solde courant : ${money(q.cash)}. Solde disponible après dépenses et épargne prévues : ${money(q.available)}.</p></div><div class="report-section"><h3>3. Répartition par catégorie</h3><table class="simulation-table"><thead><tr><th>Catégorie</th><th>Payé</th><th>Prévu</th><th>Part du total engagé</th></tr></thead><tbody>${q.byCategory.filter(c=>c.spent).map(c=>`<tr><td>${esc(c.name)}</td><td>${money(c.paid)}</td><td>${money(c.spent-c.paid)}</td><td>${pct(q.committed?c.spent/q.committed*100:0)}</td></tr>`).join('')||'<tr><td colspan="4">Aucune dépense enregistrée.</td></tr>'}</tbody></table></div><div class="report-section"><h3>4. Analyse du budget</h3><p>Enveloppe : ${money(q.totalBudget)}. Total engagé : ${money(q.committed)}. ${q.totalBudget?(q.remaining<0?'Dépassement : '+money(-q.remaining):'Budget restant : '+money(q.remaining)):'Budget non défini'}.</p>${q.byCategory.filter(c=>c.limit&&c.spent>c.limit).map(c=>`<p>${esc(c.name)} dépasse son enveloppe de ${money(c.spent-c.limit)}.</p>`).join('')}</div><div class="report-section"><h3>5. Bilan de l’épargne</h3><p>Versements du mois : ${money(q.saved)}. Taux d’épargne : ${pct(q.rate)}. Objectif mensuel : ${money(S.settings.monthlyGoal)}. Épargne déclarée à la fin du mois : ${money(q.reserve)}.</p><p>Versements de l’année jusqu’à ce mois : ${money(yearSaved)} / objectif annuel de ${money(S.settings.annualGoal)}.</p>${S.goals.map(g=>`<p>${esc(g.name)} : ${money(F.goalValue(S,g,month))} sur ${money(g.target)}.</p>`).join('')}</div><div class="report-section"><h3>6. Évolution financière</h3><p>${prev.tx.length?`Marge revenus reçus − dépenses payées : ${money(q.surplus)}, contre ${money(prev.surplus)} le mois précédent. Écart : ${money(q.surplus-prev.surplus)}. Comparaison sur les données saisies, mois potentiellement incomplets.`:'Renseignez le mois précédent pour établir une comparaison.'}</p><p>Évaluation : ${h.label}${h.score===null?'':' · '+h.score+' critère(s) rempli(s) sur 4'}.</p>${h.items.map(i=>`<p>${i.ok?'✓':'○'} ${i.name} — ${i.detail}</p>`).join('')}</div><div class="report-section"><h3>7. Observations et recommandations personnalisées</h3>${observations(q).slice(1).map(o=>`<p><strong>${esc(o.tag)} — ${esc(o.title)}.</strong> ${esc(o.text)}</p>`).join('')||'<p>Ajoutez vos mouvements pour obtenir des observations calculées.</p>'}</div><div class="report-section"><h3>8. Objectifs du mois suivant</h3><p>Priorité personnelle : ${esc(S.settings.priority)}.</p><p>${q.remaining<0?'Réexaminer les dépenses prévues et adapter les enveloppes dépassées.':'Préparer les échéances et ajuster les limites aux dépenses essentielles.'} ${q.capacity>0?'Repère indicatif d’épargne, si la situation reste identique : '+money(q.recommended)+'.':'Préserver la trésorerie avant d’augmenter les versements d’épargne.'}</p></div><p class="small muted">Méthode : seules les opérations reçues, payées ou effectuées sont retenues comme réalisées. Les opérations prévues servent à réserver le budget et le solde. Les transferts internes sont neutres. Les projections supposent une situation constante, sans rendement ni inflation.</p></section>`}
function settingsPage(){return `<div class="section-grid"><section class="panel"><h2>Mes préférences</h2><form id="settings-form" style="margin-top:23px"><div class="form-grid"><label class="field">Votre prénom ou pseudonyme<input name="name" type="text" maxlength="40" value="${esc(S.settings.name)}" placeholder="Comment vous appeler ?"></label><label class="field">Devise<select name="currency">${[['XOF','FCFA — XOF'],['XAF','FCFA — XAF'],['EUR','Euro — EUR'],['USD','Dollar américain — USD'],['GBP','Livre sterling — GBP'],['CAD','Dollar canadien — CAD'],['MAD','Dirham — MAD'],['GNF','Franc guinéen — GNF']].map(([k,n])=>`<option value="${k}" ${k===S.settings.currency?'selected':''}>${n}</option>`).join('')}</select><small>Change l’unité affichée, sans convertir les montants.</small></label><label class="field">Solde courant initial (${S.settings.currency})<input type="text" name="openingCash" inputmode="decimal" value="${numInput(S.settings.openingCash)}" required><small>Hors épargne, au début de la date ci-contre.</small></label><label class="field">Date du solde initial<input type="date" name="openingDate" value="${S.settings.openingDate}" required><small>Les mouvements antérieurs n’affectent pas le solde courant.</small></label><label class="field">Épargne initiale déclarée (${S.settings.currency})<input type="text" name="initialSaved" inputmode="decimal" value="${numInput(S.settings.initialSaved)}" required><small>Avant les versements enregistrés ; n’incluez pas ces versements une seconde fois.</small></label><label class="field">Budget par défaut des nouveaux mois<input type="text" name="monthlyBudget" inputmode="decimal" value="${numInput(S.settings.monthlyBudget)}" required><small>Utilisé en l’absence de budget d’un mois antérieur.</small></label><label class="field full">Ma priorité financière<input type="text" name="priority" maxlength="160" value="${esc(S.settings.priority)}" required></label></div><div class="notice error" id="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Enregistrer mes préférences</button></div></form></section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Mes données, sous mon contrôle</h2><p class="panel-sub">Une copie pour garder l’esprit tranquille.</p></div>${I('lock')}</div><p class="small muted">Vos données sont enregistrées dans ce navigateur, sur cet appareil. Elles ne sont pas synchronisées entre appareils. La navigation privée ou l’effacement des données du navigateur peut les supprimer.</p><div class="button-row" style="margin-top:20px">${button('Sauvegarder en JSON','backup','down','primary')}${button('Exporter en CSV','csv-all','down')}${button('Importer des données','import','up')}</div><div class="notice">JSON : restauration complète. CSV : import et export de mouvements avec les colonnes françaises fournies par l’application. Le fichier CSV s’ouvre dans Excel. L’export natif .xlsx n’est pas proposé.</div><div class="button-row">${button('Modèle CSV','csv-template','down')}${button('Exporter la copie locale brute','raw-backup','down')}</div></section><section class="panel"><h2>Découvrir sans inventer ses finances</h2><p class="panel-sub" style="margin-bottom:18px">La démonstration est fictive et isolée de vos données personnelles.</p>${button(S.demo?'Quitter la démonstration':'Charger un exemple fictif',S.demo?'exit-demo':'demo','spark')}</section><section class="panel"><h2>Réinitialiser cet espace</h2><p class="panel-sub" style="margin:8px 0 18px">Supprime les données personnelles de ce navigateur. Une confirmation et une sauvegarde sont proposées.</p>${button('Effacer mes données','reset','trash','danger')}</section></div><section class="panel span2"><div class="panel-head"><div><h2>Mes catégories de dépenses</h2><p class="panel-sub">Personnalisez vos catégories, sous-catégories et leur classification.</p></div>${button('Nouvelle catégorie','category','plus')}</div><div class="section-grid">${S.categories.map(c=>`<div class="category-row"><div class="project-icon" style="color:${c.color}">${I(c.icon)}</div><div class="category-name">${esc(c.name)}<small>${c.group==='need'?'Besoin essentiel':'Envie / loisir'} · ${c.sub.length} sous-catégories</small></div><button data-edit-category="${esc(c.id)}" aria-label="Modifier ${esc(c.name)}">${I('edit')}</button><button data-delete-category="${esc(c.id)}" aria-label="Supprimer ${esc(c.name)}">${I('trash')}</button></div>`).join('')}</div></section></div>`}
const modal=document.getElementById('modal');
function openModal(title,content,onSubmit){if(modal.open)modal.close();modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="Fermer">${I('close')}</button></div>${content}`;modal.showModal();if(onSubmit)modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const err=modal.querySelector('[role="alert"]');if(err)err.textContent='';try{onSubmit(new FormData(e.target),e.target)}catch(error){if(err)err.textContent=error.message;else toast(error.message)}})}
function field(label,name,value='',extra='',cls=''){return `<label class="field ${cls}">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`}
function txForm(kind='expense',tx=null,date=null,goal=''){
 const t=tx||{kind,date:date||month+'-'+String(Math.min(+F.today().slice(8),F.days(month))).padStart(2,'0'),description:'',amount:0,category:S.categories[0]?.id||'',sub:'',payment:'Mobile money',type:'variable',status:'paid',frequency:'once',source:incomeSources[0],goal};
 openModal(tx?'Modifier le mouvement':'Ajouter un mouvement',`<form id="tx-form"><div class="form-grid"><label class="field full">Type de mouvement<select name="kind" id="tx-kind">${Object.entries(kindNames).map(([k,v])=>`<option value="${k}" ${t.kind===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('Libellé','description',t.description,'type="text" maxlength="160" required placeholder="Ex. Courses de la semaine"','full')}${field('Montant ('+S.settings.currency+')','amount',t.amount?numInput(t.amount):'','type="text" inputmode="decimal" required placeholder="0"')}${field('Date','date',t.date,'type="date" min="1900-01-01" max="2199-12-31" required')}<label class="field tx-expense">Catégorie<select name="category" id="tx-category">${S.categories.map(c=>`<option value="${esc(c.id)}" ${t.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field tx-expense">Sous-catégorie<select name="sub" id="tx-sub"></select></label><label class="field full tx-income">Source du revenu<select name="source">${incomeSources.map(s=>`<option ${t.source===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field full tx-saving">Objectif d’épargne<select name="goal"><option value="">Épargne libre</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${g.id===t.goal?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label class="field">Nature<select name="type">${Object.entries(typeNames).map(([k,v])=>`<option value="${k}" ${t.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Statut<select name="status" id="tx-status"><option value="paid" ${t.status==='paid'?'selected':''}>Effectué / reçu / payé</option><option value="planned" ${t.status==='planned'?'selected':''}>Prévu / attendu</option></select></label><label class="field">Fréquence<select name="frequency">${Object.entries(freqNames).map(([k,v])=>`<option value="${k}" ${t.frequency===k?'selected':''}>${v}</option>`).join('')}</select><small>Aucune création automatique lors d’un changement de mois.</small></label><label class="field">Moyen de paiement<select name="payment">${['Mobile money','Espèces','Virement bancaire','Carte bancaire','Prélèvement','Chèque','Autre'].map(v=>`<option ${t.payment===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field full">Description facultative<textarea name="notes" maxlength="500" placeholder="Une précision utile…">${esc(t.notes||'')}</textarea></label></div><div class="notice" id="kind-help"></div><div class="notice error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn primary">${I('check')}Enregistrer</button></div></form>`,fd=>{
 const k=fd.get('kind');const next={...(tx||{}),id:tx?.id||F.uid(),kind:k,description:fd.get('description').trim(),amount:F.amount(fd.get('amount')),date:fd.get('date'),category:k==='expense'?fd.get('category'):'',sub:k==='expense'?fd.get('sub'):'',source:k==='income'?fd.get('source'):'',goal:k==='saving'?fd.get('goal'):'',type:fd.get('type'),status:fd.get('status'),payment:fd.get('payment'),frequency:fd.get('frequency'),notes:fd.get('notes').trim(),recurringDay:+fd.get('date').slice(8,10)};F.validateTx(next,S);if(tx)S.transactions=S.transactions.map(x=>x.id===tx.id?next:x);else S.transactions.push(next);F.ensureMonth(S,next.date.slice(0,7));persist();modal.close();render();toast('Mouvement enregistré'+(next.date.slice(0,7)!==month?' pour '+monthName(next.date.slice(0,7)):'')+'.');
 });
 const sub=()=>{const list=cat(modal.querySelector('#tx-category').value)?.sub||[];modal.querySelector('#tx-sub').innerHTML='<option value="">Sans précision</option>'+list.map(v=>`<option ${v===t.sub?'selected':''}>${esc(v)}</option>`).join('')};
 const kindUpdate=()=>{const k=modal.querySelector('#tx-kind').value;['expense','income','saving'].forEach(v=>modal.querySelectorAll('.tx-'+v).forEach(el=>el.classList.toggle('hidden',v!==k)));modal.querySelector('#kind-help').textContent=k==='saving'?'Un versement d’épargne réduit le solde courant et augmente l’épargne. Il ne compte pas comme dépense.':k==='transfer'?'Transfert entre vos comptes courants : effet neutre sur les revenus, les dépenses et le solde consolidé. Pour alimenter votre épargne, choisissez « Épargne ».':k==='income'?'Seuls les revenus marqués reçus / effectués augmentent le solde disponible.':'Une dépense prévue réserve le budget et le solde. La marquer payée ne la compte pas une seconde fois.'};
 sub();kindUpdate();modal.querySelector('#tx-category').addEventListener('change',sub);modal.querySelector('#tx-kind').addEventListener('change',kindUpdate);
}
function goalForm(id){const g=S.goals.find(g=>g.id===id)||{name:'',target:0,initial:0,deadline:'',icon:'goal'};openModal(id?'Modifier mon objectif':'Un nouveau projet à financer',`<form><div class="form-grid">${field('Nom du projet','name',g.name,'type="text" required maxlength="100" placeholder="Ex. Fonds d’urgence"','full')}${field('Montant cible ('+S.settings.currency+')','target',numInput(g.target),'type="text" inputmode="decimal" required')}${field('Déjà épargné avant les versements saisis','initial',numInput(g.initial),'type="text" inputmode="decimal" required')}${field('Date limite facultative','deadline',g.deadline,'type="date" min="1900-01-01" max="2199-12-31"')}<label class="field">Symbole<select name="icon">${[['goal','Projet personnel'],['shield','Fonds d’urgence'],['sun','Voyage'],['home','Logement'],['chart','Entreprise / investissement'],['wallet','Achat']].map(([k,v])=>`<option value="${k}" ${g.icon===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="notice">Le montant initial de l’objectif ne crée ni revenu ni dépense. Les nouveaux versements liés s’ajoutent ensuite à sa progression. Pour le total de vos réserves, renseignez aussi votre épargne initiale globale dans les paramètres.</div><div class="notice error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Annuler</button><button class="btn primary" type="submit">Enregistrer l’objectif</button></div></form>`,fd=>{const next={id:id||F.uid(),name:fd.get('name').trim(),target:F.amount(fd.get('target')),initial:F.amount(fd.get('initial')),deadline:fd.get('deadline'),icon:fd.get('icon')};if(!next.name||next.target<=0)throw Error('Indiquez un nom et un objectif strictement positif.');if(next.initial>next.target)throw Error('Le montant initial ne doit pas dépasser la cible.');if(S.goals.some(x=>x.id!==next.id&&x.name.toLocaleLowerCase('fr')===next.name.toLocaleLowerCase('fr')))throw Error('Un objectif porte déjà ce nom.');if(id)S.goals=S.goals.map(x=>x.id===id?next:x);else S.goals.push(next);persist();modal.close();render();toast('Objectif enregistré.')})}
function categoryForm(id){const c=cat(id)||{name:'',sub:[],color:'#78966c',group:'need',icon:'wallet'};openModal(id?'Modifier la catégorie':'Nouvelle catégorie',`<form><div class="form-grid">${field('Nom de la catégorie','name',c.name,'type="text" required maxlength="80"','full')}<label class="field full">Sous-catégories (une par ligne)<textarea name="sub" maxlength="5000">${esc(c.sub.join('\n'))}</textarea></label><label class="field">Classification<select name="group"><option value="need" ${c.group==='need'?'selected':''}>Besoin essentiel</option><option value="want" ${c.group==='want'?'selected':''}>Envie / loisir</option></select></label>${field('Couleur','color',c.color,'type="color" required')}</div><div class="notice error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn primary">Enregistrer</button></div></form>`,fd=>{const name=fd.get('name').trim();if(!name)throw Error('Indiquez un nom de catégorie.');if(S.categories.some(x=>x.id!==id&&x.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr')))throw Error('Cette catégorie existe déjà.');const sub=[...new Set(fd.get('sub').split('\n').map(v=>v.trim()).filter(Boolean))];if(sub.some(v=>v.length>100))throw Error('Chaque sous-catégorie doit rester sous 100 caractères.');const next={id:id||F.uid(),name,sub,group:fd.get('group'),color:fd.get('color'),icon:c.icon};if(id)S.categories=S.categories.map(c=>c.id===id?next:c);else S.categories.push(next);persist();modal.close();render();toast('Catégorie enregistrée.')})}
function confirmDialog(title,text,action,label='Confirmer',danger=false){openModal(title,`<form><p class="small muted">${esc(text)}</p><div class="notice error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn ${danger?'danger':'primary'}">${label}</button></div></form>`,()=>{modal.close();action()})}
function recurringDialog(){const source=S.transactions.filter(t=>t.date.slice(0,7)<month&&t.frequency!=='once');openModal('Préparer les mouvements récurrents',`<form><p class="small muted">Reprendre les séries récurrentes antérieures pour ${monthName()}, au statut « prévu ». Les occurrences déjà présentes ne seront pas ajoutées à nouveau. Fréquences mensuelles, hebdomadaires, trimestrielles et annuelles prises en charge.</p><div class="notice">${source.length?'Des mouvements récurrents antérieurs sont disponibles.':'Aucun mouvement récurrent antérieur. Ajoutez-en avec une fréquence différente de « Ponctuelle ».'}</div><div class="form-actions"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn primary" ${source.length?'':'disabled'}>Préparer ce mois</button></div></form>`,()=>{const count=F.recurring(S,month);persist();modal.close();render();toast(count+' mouvement(s) prévu(s) ajouté(s).')})}
function bind(){
 const byId=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);
 byId('month','change',e=>changeMonth(e.target.value));
 byId('search','input',e=>{filters.q=e.target.value;updateTransactions()});
 for(const [id,k] of [['category-filter','category'],['status-filter','status'],['nature-filter','nature'],['source-filter','source']])byId(id,'change',e=>{filters[k]=e.target.value;updateTransactions()});
 byId('framework','change',e=>{S.settings.framework=e.target.checked;persist();render()});
 byId('comparison-year','change',e=>{year=+e.target.value;comparison='year';render()});
 byId('budget-form','submit',e=>saveForm(e,fd=>{const b={total:F.amount(fd.get('total')),limits:{}};for(const c of S.categories)b.limits[c.id]=F.amount(fd.get('limit-'+c.id));if(Object.values(b.limits).reduce((a,n)=>a+n,0)>b.total)throw Error('La somme des enveloppes dépasse le budget total. Ajustez le total ou les catégories.');S.budgets[month]=b;return 'Budget enregistré pour '+monthName()+'.'}));
 byId('saving-settings','submit',e=>saveForm(e,fd=>{const next={...S.settings};for(const k of ['monthlyGoal','annualGoal','buffer'])next[k]=F.amount(fd.get(k));next.salaryPercent=+fd.get('salaryPercent');if(!Number.isFinite(next.salaryPercent)||next.salaryPercent<0||next.salaryPercent>100)throw Error('Le pourcentage doit être compris entre 0 et 100.');S.settings=next;return 'Préférences d’épargne enregistrées.'}));
 byId('settings-form','submit',e=>{e.preventDefault();const fd=new FormData(e.target);const apply=()=>saveForm(e,()=>{const next={...S.settings};for(const k of ['openingCash','initialSaved','monthlyBudget'])next[k]=F.amount(fd.get(k));for(const k of ['name','priority','currency','openingDate'])next[k]=fd.get(k).trim();if(!next.openingDate)throw Error('Indiquez la date du solde initial.');S.settings=next;return 'Préférences enregistrées.'});if(fd.get('currency')!==S.settings.currency)confirmDialog('Changer l’unité monétaire',`Les montants conserveront leur valeur numérique. Aucun taux de change n’est appliqué. Passer de ${S.settings.currency} à ${fd.get('currency')} ?`,apply,'Changer la devise');else apply()});
 for(const k of ['raise','cut','extra','saving','target','purchase'])byId('sim-'+k,'input',()=>{try{const n=k==='raise'||k==='cut'?+document.getElementById('sim-'+k).value:F.amount(document.getElementById('sim-'+k).value||'0');simulation[k]=n;document.getElementById('sim-error').textContent='';if(k==='raise'||k==='cut')document.getElementById(k+'-output').textContent=pct(n);document.getElementById('simulation-results').innerHTML=simulationResults(F.metrics(S,month))}catch(err){document.getElementById('sim-error').textContent=err.message}});
}
function saveForm(e,fn){e.preventDefault();try{const note=fn(new FormData(e.target));persist();render();toast(note)}catch(err){e.target.querySelector('[role="alert"]').textContent=err.message}}
function changeMonth(m){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(m)||m<'1900-01'||m>'2199-12')return;month=m;F.ensureMonth(S,month);persist();render()}
function updateTransactions(){const kind=page==='income'?'income':'expense',list=filtered(kind);document.getElementById('tx-list').innerHTML=transactionTable(list);document.getElementById('tx-count').textContent=list.length+' mouvement(s) · Total filtré : '+money(F.sum(list))}
function download(content,name,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function backup(raw=false){download(raw?(localStorage.getItem(KEY)||'{}'):JSON.stringify(S,null,2),'mon-budget-'+(S.demo?'fictif-':'')+F.today()+'.json','application/json;charset=utf-8')}
const csvHeaders=['Date','Type','Libellé','Montant','Devise','Catégorie','Sous-catégorie','Source','Moyen de paiement','Nature','Statut','Fréquence','Objectif','Identifiant','Série','Description'];
function csvCell(v){let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
function exportCSV(all=false,template=false){const list=template?[]:all?S.transactions:(page==='income'||page==='expense'?filtered(page==='income'?'income':'expense'):F.metrics(S,month).tx);const rows=list.map(t=>[t.date,kindNames[t.kind],t.description,String(t.amount/100).replace('.',','),S.settings.currency,cat(t.category)?.name||'',t.sub||'',t.source||'',t.payment||'',typeNames[t.type],t.status==='paid'?'Effectué':'Prévu',freqNames[t.frequency],S.goals.find(g=>g.id===t.goal)?.name||'',t.id,t.series||'',t.notes||'']);download('\uFEFF'+[csvHeaders,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),'mon-budget-'+(template?'modele':all?'tous-les-mouvements':month)+'.csv','text/csv;charset=utf-8');toast(template?'Modèle CSV téléchargé.':'Export CSV téléchargé.')}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const result=[],row=[];let cell='',quoted=false;const sep=text.slice(0,text.indexOf('\n')<0?text.length:text.indexOf('\n')).includes(';')?';':',';for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"'){if(cell)throw Error('Le fichier CSV contient des guillemets invalides.');quoted=true}else if(c===sep){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))result.push([...row]);row.length=0;cell=''}else cell+=c}if(quoted)throw Error('Guillemet non fermé dans le CSV.');if(cell||row.length){row.push(cell);result.push([...row])}return result}
function importCSV(text){const rows=parseCSV(text);if(rows.length<2)throw Error('Le fichier ne contient aucun mouvement.');const heads=rows.shift();for(const h of ['Date','Type','Libellé','Montant','Devise'])if(!heads.includes(h))throw Error('Colonne manquante : '+h+'. Utilisez le modèle CSV fourni.');const temp=JSON.parse(JSON.stringify(S));let skipped=0,created=0;for(const [index,row] of rows.entries()){const obj=Object.fromEntries(heads.map((h,i)=>[h,row[i]||'']));try{if(obj.Devise!==S.settings.currency)throw Error('La devise du fichier diffère de votre espace. Aucune conversion automatique.');const kind=Object.entries(kindNames).find(([,v])=>v===obj.Type)?.[0];if(!kind)throw Error('Type inconnu : '+obj.Type);let c=temp.categories.find(c=>c.name===obj.Catégorie);if(kind==='expense'&&!c){if(!obj.Catégorie)throw Error('Catégorie requise.');c={id:F.uid(),name:obj.Catégorie,color:'#78966c',icon:'wallet',sub:[],group:'need'};temp.categories.push(c)}if(c&&obj['Sous-catégorie']&&!c.sub.includes(obj['Sous-catégorie']))c.sub.push(obj['Sous-catégorie']);const g=temp.goals.find(g=>g.name===obj.Objectif);if(obj.Objectif&&!g)throw Error('Objectif inconnu. Créez-le avant l’import : '+obj.Objectif);const status=obj.Statut==='Prévu'?'planned':obj.Statut==='Effectué'?'paid':null;if(!status)throw Error('Statut attendu : Effectué ou Prévu.');const type=Object.entries(typeNames).find(([,v])=>v===obj.Nature)?.[0];const frequency=Object.entries(freqNames).find(([,v])=>v===obj.Fréquence)?.[0];const t={id:obj.Identifiant||F.uid(),date:obj.Date,kind,description:obj.Libellé,amount:F.amount(obj.Montant),category:kind==='expense'?c.id:'',sub:obj['Sous-catégorie'],source:obj.Source,payment:obj['Moyen de paiement'],type,status,frequency,goal:g?.id||'',series:obj.Série||'',notes:obj.Description||''};if(temp.transactions.some(x=>x.kind===t.kind&&x.date===t.date&&x.amount===t.amount&&x.category===t.category&&x.description.toLocaleLowerCase('fr').trim()===t.description.toLocaleLowerCase('fr').trim())){skipped++;continue}if(temp.transactions.some(x=>x.id===t.id))throw Error('Identifiant déjà utilisé avec des valeurs différentes.');F.validateTx(t,temp);temp.transactions.push(t);F.ensureMonth(temp,t.date.slice(0,7));created++}catch(err){throw Error('Ligne '+(index+2)+' : '+err.message)}}F.validateState(temp);confirmDialog('Vérifier l’import CSV',`${created} mouvement(s) à ajouter. ${skipped} doublon(s) ignoré(s). ${temp.categories.length-S.categories.length} nouvelle(s) catégorie(s). Vos mouvements existants seront conservés.`,()=>{S=temp;persist();render();toast(created+' mouvement(s) importé(s).')},'Importer les mouvements')}
function importDialog(){openModal('Importer mes données',`<div class="notice">Choisissez une sauvegarde JSON de cette application pour restaurer tout votre espace, ou un CSV au format fourni pour ajouter des mouvements. Taille maximale : 10 Mo.</div><label class="field">Fichier JSON ou CSV<input type="file" id="import-file" accept=".json,.csv,application/json,text/csv"></label><div class="notice error" id="import-error" role="alert"></div><div class="form-actions"><button class="btn" data-action="close">Fermer</button></div>`);modal.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Le fichier dépasse 10 Mo.');const text=await file.text();if(file.name.toLowerCase().endsWith('.csv')){importCSV(text);return}const imported=F.validateState(JSON.parse(text));confirmDialog('Restaurer cette sauvegarde ?',`${imported.transactions.length} mouvement(s), ${imported.categories.length} catégorie(s), ${imported.goals.length} objectif(s), devise ${imported.settings.currency}${imported.demo?' — DONNÉES FICTIVES':''}. Cette restauration remplace l’espace actuel. Téléchargez une sauvegarde avant de continuer.`,()=>{backup();S=imported;loadError='';F.ensureMonth(S,month);persist();render();toast('Sauvegarde restaurée. Une copie de l’ancien espace a été téléchargée.')},'Restaurer')
 }catch(err){const el=modal.querySelector('#import-error');if(el)el.textContent=err instanceof SyntaxError?'Le fichier JSON est invalide.':err.message;else toast(err.message)}})}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-action]');if(!b)return;
 const d=b.dataset;
 if(d.page){navigate(d.page);return}
 if(d.edit){txForm('',S.transactions.find(t=>t.id===d.edit));return}
 if(d.delete){const t=S.transactions.find(t=>t.id===d.delete);confirmDialog('Supprimer ce mouvement ?',t.description+' · '+money(t.amount)+' · '+dateName(t.date),()=>{S.transactions=S.transactions.filter(x=>x.id!==t.id);persist();render();toast('Mouvement supprimé.')},'Supprimer',true);return}
 if(d.pay){const t=S.transactions.find(t=>t.id===d.pay);t.status='paid';persist();if(modal.open)modal.close();render();toast('Mouvement marqué comme effectué.');return}
 if(d.catFilter){page='expense';filters.category=d.catFilter;render();return}
 if(d.editGoal){goalForm(d.editGoal);return}
 if(d.deleteGoal){confirmDialog('Supprimer cet objectif ?','Les versements déjà enregistrés seront conservés comme épargne libre. Le montant initial propre à cet objectif sera retiré de sa progression.',()=>{S.goals=S.goals.filter(g=>g.id!==d.deleteGoal);S.transactions.forEach(t=>{if(t.goal===d.deleteGoal)t.goal=''});persist();render();toast('Objectif supprimé. Versements conservés.')},'Supprimer',true);return}
 if(d.contribute){txForm('saving',null,null,d.contribute);return}
 if(d.editCategory){categoryForm(d.editCategory);return}
 if(d.deleteCategory){if(S.transactions.some(t=>t.category===d.deleteCategory)){toast('Cette catégorie est utilisée. Réaffectez ses mouvements avant de la supprimer.');return}confirmDialog('Supprimer cette catégorie ?','La catégorie et ses enveloppes seront retirées. Les autres catégories seront conservées.',()=>{S.categories=S.categories.filter(c=>c.id!==d.deleteCategory);Object.values(S.budgets).forEach(b=>delete b.limits[d.deleteCategory]);persist();render();toast('Catégorie supprimée.')},'Supprimer',true);return}
 if(d.day){const tx=F.metrics(S,month).tx.filter(t=>t.date===d.day);const goals=S.goals.filter(g=>g.deadline===d.day);openModal('Le '+dateName(d.day),transactionTable(tx)+goals.map(g=>`<div class="notice">Échéance : ${esc(g.name)} · ${money(Math.max(0,g.target-F.goalValue(S,g,month)))} à financer.</div>`).join('')+`<div class="form-actions"><button class="btn" data-add-day="${d.day}">${I('plus')}Ajouter un mouvement</button></div>`);return}
 if(d.addDay){txForm('expense',null,d.addDay);return}
 if(d.comparison){comparison=d.comparison;render();return}
 if(d.cut){simulation.cut=+d.cut;document.getElementById('sim-cut').value=d.cut;document.getElementById('cut-output').textContent=pct(+d.cut);document.getElementById('simulation-results').innerHTML=simulationResults(F.metrics(S,month));return}
 const a=d.action;if(!a)return;
 if(a.startsWith('add-')){txForm(a.slice(4));return}
 const actions={
 close:()=>modal.close(),menu:()=>{menuOpen=!menuOpen;document.querySelector('.sidebar').classList.toggle('open',menuOpen);document.querySelector('.backdrop').classList.toggle('open',menuOpen)},theme:()=>{S.settings.theme=S.settings.theme==='dark'?'light':'dark';persist();render()},prev:()=>changeMonth(F.shift(month,-1)),next:()=>changeMonth(F.shift(month,1)),goal:()=>goalForm(),category:()=>categoryForm(),categories:()=>navigate('settings'),recurring:recurringDialog,
 'copy-budget':()=>{const prior=S.budgets[F.shift(month,-1)];if(!prior){toast('Aucun budget pour le mois précédent.');return}confirmDialog('Reprendre le budget précédent ?',`Les limites de ${monthName(F.shift(month,-1))} remplaceront les enveloppes de ${monthName()}. Aucun mouvement ne sera copié.`,()=>{S.budgets[month]=JSON.parse(JSON.stringify(prior));persist();render();toast('Enveloppes reprises.')},'Reprendre')},
 demo:()=>{if(S.demo){navigate('dashboard');return}if(!loadError)persist();S=F.demo(month);F.ensureMonth(S,month);page='dashboard';render();toast('Exemple fictif chargé. Vos données personnelles sont conservées séparément.')},
 'exit-demo':()=>{try{const raw=localStorage.getItem(KEY);S=raw?F.validateState(JSON.parse(raw)):F.fresh()}catch{S=F.fresh()}F.ensureMonth(S,month);render();toast('Votre espace personnel est restauré.')},
 csv:()=>exportCSV(), 'csv-all':()=>exportCSV(true),'csv-template':()=>exportCSV(false,true),backup:()=>backup(),'raw-backup':()=>backup(true),import:importDialog,print:()=>window.print(),
 reset:()=>confirmDialog('Effacer les données de cet espace ?',`Une sauvegarde sera téléchargée avant la suppression. ${S.demo?'Seule la démonstration sera réinitialisée.':'Les mouvements, budgets, objectifs et préférences enregistrés dans ce navigateur seront supprimés.'}`,()=>{backup();const demo=S.demo;S=F.fresh();S.demo=demo;loadError='';F.ensureMonth(S,month);persist();page='dashboard';render();toast('Espace réinitialisé. La sauvegarde a été téléchargée.')},'Sauvegarder puis effacer',true)
 };actions[a]?.();
});
document.addEventListener('pointermove',e=>{const el=e.target.closest('[data-tip]'),tip=document.getElementById('tooltip');if(!el){tip.style.display='none';return}tip.textContent=el.dataset.tip;tip.style.display='block';tip.style.left=Math.min(e.clientX+12,window.innerWidth-tip.offsetWidth-12)+'px';tip.style.top=Math.max(8,e.clientY-tip.offsetHeight-12)+'px'});
document.addEventListener('invalid',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('Vérifiez ce champ : renseignez une valeur valide en respectant les limites indiquées.');},true);
document.addEventListener('input',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('');});
window.addEventListener('storage',e=>{if(e.key===KEY&&!S.demo)toast('Les données ont changé dans un autre onglet. Rechargez cette page avant de poursuivre.')});
render();
